SELECT , ru.nickname AS reply_to_nickname, LEFT(p.content, 120) AS reply_to_content FROM blog_message m JOIN sys_user u ON u.user_id = m.user_id LEFT JOIN blog_message p ON p.message_id = m.parent_id LEFT JOIN sys_user ru ON ru.user_id = p.user_id WHERE m.message_id IN
#{id}
ORDER BY m.create_time, m.message_id

